/**
 * Backup / export service (Directive §10).
 *
 * Provides a versioned JSON export manifest of all record tables plus an
 * evidence manifest (paths + integrity hashes). OPFS media bytes are NOT
 * embedded in the JSON export — a full capsule (records + media) is the
 * future WP-10 archive format. Until restore is implemented and tested,
 * this export is a BACKUP FOUNDATION, not full recovery (documented).
 *
 * Security: exports may contain client PII. They are generated locally,
 * never uploaded, and should be stored by the user in a location they
 * control. Optional AES-GCM passphrase encryption is planned for the
 * capsule format (WP-10).
 */
import type { TPIDatabase } from "./db";
import { snapshotDatabase, type ExportManifest } from "./data/migrations";
import { hashBlob } from "./files/opfs.hash";

export const EXPORT_FORMAT_VERSION = 1;

export async function exportAll(db: TPIDatabase): Promise<ExportManifest> {
  const manifest = await snapshotDatabase(db);
  return { ...manifest, manifestVersion: EXPORT_FORMAT_VERSION };
}

/** Serialize + hash an export so the backup file itself has recorded integrity. */
export async function serializeExport(
  manifest: ExportManifest,
): Promise<{ json: string; sha256: string }> {
  const json = JSON.stringify(manifest, null, 2);
  const sha256 = await hashBlob(new TextEncoder().encode(json).buffer);
  return { json, sha256 };
}

/**
 * Validate an export manifest: structure, version, table presence, evidence
 * manifest shape, and hash format.
 */
export function validateExport(manifest: unknown): string[] {
  const errors: string[] = [];
  if (typeof manifest !== "object" || manifest === null) {
    return ["Export manifest must be a JSON object"];
  }
  const m = manifest as Record<string, unknown>;
  if (m.manifestVersion !== 1) errors.push("manifestVersion must be 1");
  if (typeof m.schemaVersion !== "number") errors.push("schemaVersion missing");
  if (typeof m.exportedAt !== "number") errors.push("exportedAt missing");
  if (typeof m.tables !== "object" || m.tables === null) {
    errors.push("tables missing");
  } else {
    const required = ["cases", "auditEvents"];
    const tables = m.tables as Record<string, unknown>;
    for (const name of required) {
      if (!Array.isArray(tables[name])) errors.push(`tables.${name} must be an array`);
    }
  }
  if (!Array.isArray(m.evidenceManifest)) {
    errors.push("evidenceManifest must be an array");
  } else {
    for (const entry of m.evidenceManifest as Array<Record<string, unknown>>) {
      if (typeof entry.id !== "string") errors.push("evidenceManifest entry missing id");
      if (typeof entry.contentHash !== "string" || !/^[0-9a-f]{64}$/.test(entry.contentHash)) {
        errors.push(`evidenceManifest entry ${String(entry.id)} has invalid contentHash`);
      }
    }
  }
  return errors;
}
